#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структура работы с задвижкойtypedef struct : public Queue_PRS  {  CShKVO sh;  bool mPress;  bool mOn;  bool m_bClose;  bool m_bNoSendHs;  int nNoSendHs;  bool bStopor;  } Queue_KvoST;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintKvoST(DefinePaint)  {  QueueP(Queue_KvoST);  //  if (p->nNoSendHs>= 0 )  {		CShHS& Sh = (CShHS&)q.m_pPipe->SH(p->nNoSendHs);		if ( Sh.RetCode == CShBase::rcOK )		{		    p->m_bNoSendHs = Sh.mOn;		}  }  if ( !p->m_bPressed )    {    CShKVO* sh = (CShKVO*)PipeSh;	if (p->nSocketNumber!=-1)		sh=(CShKVO*)q.m_pSocket->Sh(p->nSocketNumber);    if ( IsTypeOk )      {      memcpy( &p->sh, sh, sizeof( p->sh ) );      p->mOn    =  sh->Eq_State( CKVO::On );      p->mPress = (sh->Ctrl_Flags&CKVO::Set_On) ? 1 : 0;	  p->m_bClose=p->sh.Is_Ctrl(CKVO::Set_Off);	  p->bStopor    = sh->Eq_State( CKVO::Stopor );      }    }  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~static void fnSendData(void* base,void* pVoid,bool bMessage)  {  ASS( base )  Queue_KvoST* p = (Queue_KvoST*)base;  if ( !ISTypeOK ) return;  if (p->m_bNoSendHs)	  return;  //  if ( pVoid == &p->mPress )    {    bMessage = true;    int Old = p->mPress ? 1 : 0;    int New = p->mPress ? CKVO::Set_On : CKVO::Set_Off;    p->send.Set( &Old, &New );    }  else    {       p->send.SetNew( pVoid );    }  if (p->nSocketNumber!=-1)  {  	    if (p->send.eType==enumValueInt)		{			double dValue=p->send.nNew;			if (lstrcmp(p->send.szValue,"Вкл/Выкл")==0)			{				if (dValue==CKVO::Set_On)					dValue=1;				else				if (dValue==CKVO::Set_Off)					dValue=0;			}			p->pSocket->SetSocketValue(id_KVO, p->send.szName, p->send.szValue,dValue, p->send.dOld, bMessage, p->send.eType);		}  }  else		p->pPipe->SendData( p->send, bMessage );  p->m_bPressed = !bMessage;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void FillKVO( SPriborBase* d, void* pp )  {  d->fnData = fnSendData;  Queue_KvoST* p = (Queue_KvoST*)pp;  if ( lstrcmp( p->send.szName, "ON/OFF" ) == 0 )  {    d->pVoid = &p->mPress;	d->pbBlock = &p->bStopor;  }  else  if ( d->pVoid == &p->sh.State_Flags && lstrcmp( p->send.szValue, "Включен" ) == 0 )       d->pVoid =  &p->mOn;  else  if ( lstrcmp( p->send.szValue, "Показания" ) == 0 )    {    d->eType = enumValueBol;    d->pVoid = &p->mOn;    }  else  if ( d->pVoid == &p->sh.Ctrl_Flags && lstrcmp( p->send.szValue, "Остановить" ) == 0 )       d->pVoid =  &p->m_bClose;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddKvoST(DefineTegs)  {  AddQueueEx(Queue_KvoST);  //  CShKVO sh;  memcpy( &p->sh, &sh, sizeof(sh) );  p->pSH = &p->sh;  p->nSocketNumber=-1;    // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintKvoST;  p->m_bNoSendHs=false;  p->nNoSendHs=-1;  p->bStopor=false;  char szSuffNoSend[64] = "";    STegObj obj[] =    {	{ 'S', "suffNoSend", szSuffNoSend, 63 },    // Дополнительная информация    EXT_QUEUE    };::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  if (*szSuffNoSend)  {	  int nActive;	  nActive=def.GetActiveObjSocket();	  const char* name = def.GetModelName(nActive);      char szName[128];      sprintf_s( szName, sizeof(szName), "%s%s", name, szSuffNoSend );      p->nNoSendHs=def.AddKindPipe(id_HS,szName);      def.m_queue.m_pPipe->End();  }  //  AddPribors( def, teg, Buffer, p, &FillKVO, id_KVO );  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~